        // If sendMoney reverted, the balance should remain the same before and after withdrawAll
        if (success) {
            assertTrue(balanceAfter == 0, "After successful sendMoney, withdrawAll should drain all funds");
        } else {
            assertTrue(balanceAfter == balanceBefore, "After failed sendMoney, withdrawAll should not change balance");
        }
